// === repo.js ===
export function buatRepoMemori(awal = []) {
  const data = awal.map((p) => ({ ...p }));
  let nextId = data.length + 1;
  return {
    async semua() { return data.map((p) => ({ ...p })); },
    async cariNama(nama) { return data.find((p) => p.nama.toLowerCase() === nama.toLowerCase()) ?? null; },
    async tambah(p) { const baru = { id: nextId++, ...p }; data.push(baru); return { ...baru }; },
  };
}
// === service.js ===
export function buatProdukService(repo) {
  return {
    async tambah({ nama, harga }) {
      if (await repo.cariNama(nama)) throw Object.assign(new Error(`${nama} sudah ada`), { status: 409 });
      return repo.tambah({ nama, harga });
    },
    async daftar() {
      return (await repo.semua()).map((p) => p.nama);
    },
  };
}
// === main.js ===
import { buatRepoMemori } from './repo.js';
import { buatProdukService } from './service.js';

const tokoA = buatProdukService(buatRepoMemori([{ id: 1, nama: 'Kopi', harga: 18000 }]));
const tokoB = buatProdukService(buatRepoMemori());

console.log(await tokoA.tambah({ nama: 'Teh', harga: 12000 }));
try {
  await tokoA.tambah({ nama: 'KOPI', harga: 1 });
} catch (e) {
  console.log(e.status, e.message);
}
await tokoB.tambah({ nama: 'Kopi', harga: 20000 });
console.log(await tokoA.daftar(), await tokoB.daftar());

const semua = await buatRepoMemori([{ id: 1, nama: 'Roti' }]).semua();
semua[0].nama = 'Diubah dari luar';

