function buatPenghitung(simpan) {
  return {
    async tambah(n) {
      const baru = (await simpan.ambil()) + n;
      await simpan.tulis(baru);
      return baru;
    },
  };
}
let nilai = 10;
const simpanMemori = {
  async ambil() { return nilai; },
  async tulis(n) { nilai = n; },
};
console.log(await buatPenghitung(simpanMemori).tambah(5));
